export function getActivePictures(): PPDTPicture[] {
  return PPDT_PICTURES.filter(p => p.active !== false);
}

export function getPictureByNumber(num: number): PPDTPicture | null {
  const active = getActivePictures();
  if (num < 1 || num > active.length) return null;
  return active[num - 1];
}

export function getPictureNumberById(id: string): number | null {
  const active = getActivePictures();
  const idx = active.findIndex(p => p.id === id);
  return idx >= 0 ? idx + 1 : null;
}
